package org.usbworkbench;
import java.io.*;import java.nio.file.*;import java.util.*;
public final class BatchToolsTest {
 static int checks;static void check(boolean b,String text){checks++;if(!b)throw new AssertionError(text);}interface A{void run()throws Exception;}static void fails(String text,A action)throws Exception{try{action.run();throw new AssertionError(text);}catch(IOException e){check(e.getMessage().startsWith(text),e.toString());}}
 static final class Disk implements BlockDevice {final RandomAccessFile file;long count;int writes;boolean metadataOnly;long dataEnd;Disk(File f,long bytes)throws IOException{file=new RandomAccessFile(f,"rw");file.setLength(bytes);count=bytes/512;}public int blockSize(){return 512;}public long blockCount(){return count;}public void read(long at,byte[] b,int n)throws IOException{file.seek(at*512);file.readFully(b,0,n);}public void write(long at,byte[] b,int n)throws IOException{if(metadataOnly&&at< dataEnd+1&&at+n/512>2048)throw new IOException("TEST_FILESYSTEM_WRITE");writes++;file.seek(at*512);file.write(b,0,n);}public void sync()throws IOException{file.getFD().sync();}public void close(){try{file.close();}catch(IOException ignored){}}}
 public static void main(String[] args)throws Exception{Path root=Files.createTempDirectory("usbwb-batch-");try{
  try(Disk disk=new Disk(root.resolve("table.img").toFile(),128L*1048576)){AdvancedDiskTools.format(disk,"fat32","gpt","DATA",0,(a,b)->{});PartitionConversion.Plan plan=PartitionConversion.read(disk);check(plan.gpt&&plan.parts.size()==1,"GPT input");byte[] backup=PartitionConversion.backup(disk,plan);check(backup.length>33000&&new String(backup,0,8,"US-ASCII").equals("USBPT001"),"bounded table backup");disk.dataEnd=plan.parts.get(0).end;disk.metadataOnly=true;PartitionConversion.convert(disk,plan,"mbr",(a,b)->{});PartitionConversion.Plan mbr=PartitionConversion.read(disk);check(!mbr.gpt&&mbr.parts.get(0).start==plan.parts.get(0).start&&mbr.parts.get(0).end==plan.parts.get(0).end,"GPT to MBR same filesystem bounds");PartitionConversion.convert(disk,mbr,"gpt",(a,b)->{});check(AdvancedDiskTools.inspectGpt(disk).contains("CRC OK"),"MBR to GPT CRC and no filesystem writes");int before=disk.writes;fails("TABLE_ALREADY",()->PartitionConversion.convert(disk,PartitionConversion.read(disk),"gpt",(a,b)->{}));check(disk.writes==before,"same-type no writes");}
  try(Disk disk=new Disk(root.resolve("cancel.img").toFile(),128L*1048576)){AdvancedDiskTools.format(disk,"fat32","gpt","DATA",0,(a,b)->{});PartitionConversion.Plan plan=PartitionConversion.read(disk);int before=disk.writes;fails("CANCELLED",()->PartitionConversion.convert(disk,plan,"mbr",(a,b)->{throw new IOException("CANCELLED");}));check(disk.writes==before,"conversion cancellation checked before first write");}
  try(Disk disk=new Disk(root.resolve("full.img").toFile(),128L*1048576)){AdvancedDiskTools.format(disk,"fat32","mbr","DATA",0,(a,b)->{});int before=disk.writes;fails("TABLE_NO_ROOM",()->PartitionConversion.validateTarget(PartitionConversion.read(disk),"gpt"));check(before==disk.writes,"full-size MBR not silently shrunk");}
  try(Disk disk=new Disk(root.resolve("clone.img").toFile(),128*1024)){byte[] data=new byte[65536];new Random(6).nextBytes(data);disk.write(0,data,data.length);disk.write(128,data,data.length);ByteArrayOutputStream copy=new ByteArrayOutputStream();int writes=disk.writes;PhoneClone.clone(disk,new PhoneClone.Image(){public OutputStream output(long size){return copy;}public InputStream input(){return new ByteArrayInputStream(copy.toByteArray());}},(a,b)->{});check(copy.size()==128*1024&&writes==disk.writes,"phone clone complete and USB read only");fails("VERIFY_FAILED",()->PhoneClone.clone(disk,new PhoneClone.Image(){public OutputStream output(long size){return new ByteArrayOutputStream();}public InputStream input(){return new ByteArrayInputStream(new byte[128*1024]);}},(a,b)->{}));}
  File file=root.resolve("bench.tmp").toFile();FileBenchmark.File benchmark=new FileBenchmark.File(){public OutputStream output()throws IOException{return new FileOutputStream(file);}public InputStream input()throws IOException{return new FileInputStream(file);}public void sync()throws IOException{try(RandomAccessFile f=new RandomAccessFile(file,"rw")){f.getFD().sync();}}};String report=FileBenchmark.run(benchmark,16,(a,b)->{});check(file.length()==16*1048576&&report.contains("Full byte comparison: PASS"),"write/sync/whole file verify benchmark");fails("BENCH_SIZE",()->FileBenchmark.run(benchmark,0,(a,b)->{}));
  String sums=WorkshopTools.checksums(new ByteArrayInputStream(new byte[]{1,2,3}),3,"",(a,b)->{});check(!ReportText.render(sums,false).contains("بصمات")&&!ReportText.render(sums,false).contains("ليستا"),"English report omits Arabic prose");check(!ReportText.render(sums,true).contains("Checksums")&&!ReportText.render(sums,true).contains("legacy comparison"),"Arabic report omits English prose");check(!ReportText.render("Random read / قراءة عشوائية: 5 MiB/s",false).contains("قراءة"),"random report selected language");check(ReportText.render("GPT • CRC OK / سليم\n1 • ملف.iso • LBA 2048–9999",false).contains("ملف.iso"),"file names preserved while localizing labels");check(ReportText.render("FORMAT_OK NTFS / MBR",true).startsWith("اكتملت التهيئة"),"NTFS result and mount explanation localized");check(!ReportText.error("ENGINE_FAILED mkntfs (1)\nEnglish native diagnostic",true).contains("English native"),"Arabic error summary keeps code without mixed native prose");
  check(ReportText.render("Capacity: 100 bytes\nSector: 512 bytes\nPartition 1: type 0x7, LBA 2048, sectors 99\n",true).contains("السعة: 100 بايت"),"drive report Arabic fields");
  check(ReportText.render("السعة: 100 بايت\nالقطاع: 512 بايت\n",false).contains("Capacity: 100 bytes"),"old Arabic drive report switches to English");
  check(!ReportText.render("FS_CHECK_OK fat",true).contains("Read-only"),"Arabic filesystem check report");
  check(!ReportText.render("FS_REPAIR_OK ntfs",false).contains("إصلاح"),"English repair report");
  check(ReportText.render("FS_REPAIR_OK ntfs",true).contains("chkdsk"),"NTFS repair limit in Arabic");
  System.out.println("PASS: "+checks+" table conversion/no-data-write, phone clone/readback, file benchmark and report-language checks");
 }finally{try(java.util.stream.Stream<Path> paths=Files.walk(root)){paths.sorted(Comparator.reverseOrder()).forEach(p->{try{Files.delete(p);}catch(IOException ignored){}});}}}
}
